cat > /tmp/qa_rules_extract.py <<'EOF'
import re, os
base = os.path.expanduser('~/agents-config')
want = {
 'rules/safety-and-models.md': ['hard-rule-3'],
 'rules/responses.md': ['hard-rule-4','hard-rule-5','trigger-rule-16','trigger-rule-27','trigger-rule-41','trigger-rule-79','trigger-rule-87'],
 'rules/research.md': ['trigger-rule-49'],
}
def slug(h):
    s = re.sub(r'[^\w\- ]', '', h.strip().lower())
    return s.replace(' ', '-')
for f, ids in want.items():
    lines = open(os.path.join(base, f), encoding='utf-8').read().split('\n')
    heads = []
    for i, l in enumerate(lines):
        m = re.match(r'^(#{1,6})\s+(.*)$', l)
        if m: heads.append((i, len(m.group(1)), slug(m.group(2))))
    for idw in ids:
        start = None; lvl = None
        for i, lv, s in heads:
            if s == idw or re.match(re.escape(idw) + r'(?!\d)', s):
                start, lvl = i, lv; break
        if start is None:
            for i, l in enumerate(lines):
                if ('id="%s"' % idw) in l or ('name="%s"' % idw) in l:
                    start = i; lvl = 7; break
        print('=' * 8, f, '#' + idw, '(line %s)' % (start + 1 if start is not None else 'NOT FOUND'))
        if start is None: continue
        n = 0
        for j in range(start, len(lines)):
            if j > start:
                m = re.match(r'^(#{1,6})\s+', lines[j])
                if m and len(m.group(1)) <= lvl: break
                if lvl == 7 and ('<a id="' in lines[j] or re.match(r'^#{1,6}\s', lines[j])) and j > start + 1: break
            print(lines[j][:900]); n += 1
            if n >= 34: print('...[capped]'); break
EOF
python3 /tmp/qa_rules_extract.py

